We assume that 
\begin{enumerate}
\item $a(x)$ and $L_1,L_2,U_1,U_2$ satisfy (H1) and (H2),
\item $(z,w)\in C^1({\bf R}_+)$ satisfies $(z_0(x),w_0(x))\in\Delta_{m,x}$ and \begin{align}
\begin{split}
-\delta_1\left(1+Mx\right)^{-1-\alpha}&\leq\Phi(x,0;z_0,w_0)\leq\delta_2,\\
\delta_1\left(1+Mx\right)^{-1-\alpha}&\leq\Psi(x,0;z_0,w_0)\leq\delta_2,
\end{split}
\label{eqn:condition-initial}
\end{align}for some positive constants $\delta_1\leq \delta_2$,
\item the compatibility conditions: $w_0(0)+z_0(0)=0,\;w'_0(0)-z'_0(0)=0$.
\end{enumerate}
Then, if we choose $M$ in \eqref{eqn:H1} large enough, 
the initial boundary problem (P1) has a time global classical solution.

We assume that 
\begin{enumerate}
\item $a(x)$ and $L_1,L_2,U_1,U_2$ satisfy (H1) and (H3), 
\item $(z,w)\in C^1({\bf R}_+)$ satisfies $(z_0(x),w_0(x))\in\Delta_{r,x},\;(z_B(t),w_B(t))\in\Delta_{r,0}$ and \begin{align}&
\begin{split}
&\delta_1\left(1+Mx\right)^{-1-\alpha}\leq\Phi(x,0;z_0,w_0)\leq\delta_2,\\
&\delta_1\left(1+Mx\right)^{-1-\alpha}\leq\Psi(x,0;z_0,w_0)\leq\delta_2,
\end{split}
\label{eqn:condition-initia2}
\end{align}
\begin{align}
\begin{split}
&\delta_1\leq\Phi_B(0,t;z_B,w_B)\leq\delta_2,\\
&\delta_1\leq\Psi_B(0,t;z_B,w_B)\leq\delta_2,
\end{split}
\label{eqn:condition-boundary}
\end{align}for some positive constants $\delta_1\leq \delta_2$, 
\item the compatibility conditions: $z_0(0)=z_B(0),\;w_0(0)=w_B(0)$ and 
\begin{align*}
\begin{cases}
z'_B(0)+\lambda_1(u_0(0))z'_0(0)=\dfrac{\gamma-1}{8}a(0)
\left[\left\{w_0(0)\right\}^2-\left\{z_0(0)\right\}^2\right],\\
w'_B(0)+\lambda_2(u_0(0))w'_0(0)=-\dfrac{\gamma-1}{8}a(0)\left[\left\{w_0(0)\right\}^2-\left\{z_0(0)\right\}^2\right].
\end{cases}
\end{align*}
\end{enumerate}
Then,  if we choose $M$ in \eqref{eqn:H1} large enough, 
the initial boundary problem (P2) has a time global classical solution.

We assume that 
	\begin{enumerate}
		\item $a(x)$ and $L_1,L_2,U_1,U_2$ satisfy (H1) and (H4), 
		\item $(z,w)\in C^1({\bf R}_+)$ satisfies $(z_0(x),w_0(x))\in\Delta_{l,x}$ and \begin{align}&
			\begin{split}
				&-\delta_1\left(1+Mx\right)^{-1-\alpha}\leq\Phi(x,0;z_0,w_0)\leq\delta_2,\\
				&-\delta_1\left(1+Mx\right)^{-1-\alpha}\leq\Psi(x,0;z_0,w_0)\leq\delta_2,
			\end{split}
			\label{eqn:condition-initia3}
		\end{align}for some positive constants $\delta_1\leq \delta_2$.
	\end{enumerate}
	Then, if we choose $M$ in \eqref{eqn:H1} large enough, 
	the initial boundary problem (P3) has a time global classical solution.

\label{pro:1}
	If 
	\begin{align}
		(z_0(x),w_0(x))\in \Delta_{m,x}\quad\text{ for any $x\geq0$}
	\end{align}
	and (P1) has a smooth solution satisfying $\rho\geq0$, then, $\Delta_{m,x}$ is an invariant region for (P1).

Choosing $\varepsilon>0$ small enough, we define 
\begin{align*}
	\begin{split}
		\Delta_{m,x,\varepsilon}=&\left\{(z,w);
-\left(L_1-\varepsilon\right)e^{-\int^x_0\bar{a}(y)dy}\leq z\leq -\left(U_1+\varepsilon\right)e^{\int^x_0\bar{a}(y)dy},\right.\\
		&\left.\left(L_2+\varepsilon\right)e^{-\int^x_0\bar{a}(y)dy}\leq w\leq 
\left(U_2-\varepsilon\right)e^{\int^x_0\bar{a}(y)dy},w\geq z\right\}
	\end{split}
\end{align*}
and assume that $(z_0(x),w_0(x))\in \Delta_{m,x,\varepsilon}$. Let us 
prove $\Delta_{m,x}$ is an invariant region for (P1) by a contradiction. 
Then, from Theorem \ref{thm:local} and the finite propagation, it suffices to 
solutions on a compact set $K=[0,R]$ for a positive constant $R$.



If this does not hold, there exist $x_*\in K$ and $t_*>0$ such that the following cases occur. 
\begin{itemize}
\setlength{\parskip}{0.1cm} 
\setlength{\itemsep}{0cm} 
\item[(Case 1)\hspace*{-2ex}] \hspace*{2ex}$\underline{z}(x_*,t_*)=-L_1$,\quad $(z(x,t),w(x,t))\in 
{\rm int}(\Delta_{m,x}),\; x\in{\bf R}_+,\;t<t_*,$\vspace*{0.5ex}
\item[(Case 2)\hspace*{-2ex}] \hspace*{2ex}$z(0,t_*)=\underline{z}(0,t_*)=-L_1$,\quad $(z(x,t),w(x,t))\in {\rm int}(\Delta_{m,x}),\; x\in{\bf R}_+,\linebreak t<t_*,$\vspace*{0.5ex}
\item[(Case 3)\hspace*{-2ex}] \hspace*{2ex}$\bar{z}(x_*,t_*)=-U_1$,\quad $(z(x,t),w(x,t))\in {\rm int}(\Delta_{m,x}),\;  x\in{\bf R}_+,\;t<t_*,$\vspace*{0.5ex}
\item[(Case 4)\hspace*{-2ex}] \hspace*{2ex}${z}(0,t_*)=\bar{z}(0,t_*)=-U_1$,\quad $(z(x,t),w(x,t))\in {\rm int}(\Delta_{m,x}),\;  x\in{\bf R}_+,\linebreak t<t_*,$\vspace*{0.5ex}
\item[(Case 5)\hspace*{-2ex}] \hspace*{2ex}$\underline{w}(x_*,t_*)=L_2$,\quad $(z(x,t),w(x,t))\in {\rm int}(\Delta_{m,x}),\;  x\in{\bf R}_+,\;t<t_*,$\vspace*{0.5ex}
\item[(Case 6)\hspace*{-2ex}] \hspace*{2ex}${w}(0,t_*)=\underline{w}(0,t_*)=L_2$,\quad $(z(x,t),w(x,t))\in {\rm int}(\Delta_{m,x})
,\;  x\in{\bf R}_+,\;t<t_*,$\vspace*{0.5ex}
\item[(Case 7)\hspace*{-2ex}] \hspace*{2ex}$\bar{w}(x_*,t_*)=U_2$,\quad $(z(x,t),w(x,t))\in {\rm int}(\Delta_{m,x}),\;  x\in{\bf R}_+,\;t<t_*,$\vspace*{0.5ex}
\item[(Case 8)\hspace*{-2ex}] \hspace*{2ex}${w}(0,t_*)=\bar{w}(0,t_*)=U_2$,\quad $(z(x,t),w(x,t))\in {\rm int}(\Delta_{m,x})
,\;  x\in{\bf R}_+,\;t<t_*,$
\end{itemize}
where $\underline{z}=e^{\int^x_0\bar{a}(y)dy}{z},\;\bar{z}=e^{-\int^x_0\bar{a}(y)dy}z,\;
\underline{w}=e^{\int^x_0\bar{a}(y)dy}w,\;
\bar{w}=e^{-\int^x_0\bar{a}(y)dy}w$ and ${\rm int}(\Delta_{m,x})$ represents the interior of 
$\Delta_{m,x}$.
\vspace*{1ex}


(Case 1) We set $r=w/z$. Then, if 
$(z,w)\in \Delta_{m,x}$, 
from  $\eqref{eqn:invariant1}_1$ and $\eqref{eqn:invariant3}_2$, we notice that
\begin{align*}
-\sigma_1\leq r\leq0.
\end{align*}
Then, if 
$(z,w)\in \Delta_{m,x}$, we deduce from \eqref{eqn:diagonalization}, \eqref{eqn:f(r)>l} and \eqref{eqn:bar a} 
	\begin{align}
		e^{-\int^x_0\bar{a}(y)dy}\left(\underline{z}_t+\lambda_1\underline{z}_x\right)
=&a(x)\dfrac{\gamma-1}8\left(w^2-z^2\right)

+\bar{a}(x)\left(\dfrac{\gamma+1}4z^2+\dfrac{3-\gamma}4zw\right)\nonumber\\
=&a(x)\dfrac{\gamma-1}8z^2\left(r^2-1\right)

+\bar{a}(x)z^2\left(\dfrac{\gamma+1}4+\dfrac{3-\gamma}4r\right)\nonumber\\
>&-l\bar{a}(x)\dfrac{\gamma-1}8z^2\left|r^2-1\right|

+\bar{a}(x)z^2\left(\dfrac{\gamma+1}4+\dfrac{3-\gamma}4r\right)\nonumber\\
\geq& \dfrac{(\gamma-1)\bar{a}(x)|r^2-1|}{8}z^2\left\{f(r)-l\right\}\nonumber\\
\geq&0.
\label{eqn:maximum1}
\end{align}
In this case, $\underline{z}$ attains the minimum at $(x_*,t_*)$. Then, since $\underline{z}_x=0$ and 
$\underline{z}_t\leq0$, 
we can deduce a contradiction from \eqref{eqn:maximum1}.



\vspace*{1ex}


(Case 2) In this case, we find that $\underline{z}_t(0,t_*)\leq0$ and $\underline{z}_x(0,t_*)\geq0$. Observing Remark \ref{rem:1} (2), since $\lambda_1<0$, we can deduce a contradiction from \eqref{eqn:maximum1}.


\vspace*{1ex}


(Case 3) 	We set  $r=w/z$. Then, if 
	$(z,w)\in \Delta_{m,x}$, from $\eqref{eqn:invariant3}_2$, we notice that
		$-\sigma_1\leq r\leq0$.
	Then, if 
	$(z,w)\in \Delta_{m,x}$, we deduce from \eqref{eqn:diagonalization}, \eqref{eqn:f(r)>l} and \eqref{eqn:bar a}  
	\begin{align}
		e^{\int^x_0\bar{a}(y)dy}\left(\bar{z}_t+\lambda_1\bar{z}_x\right)
		=&a(x)\dfrac{\gamma-1}8\left(w^2-z^2\right)

		-\bar{a}(x)\left(\dfrac{\gamma+1}4z^2+\dfrac{3-\gamma}4zw\right)\nonumber\\
		<& -\dfrac{(\gamma-1)\bar{a}(x)|r^2-1|}{8}z^2\left\{f(r)-l\right\}\nonumber\\
		\leq&0.
\label{eqn:maximum2}
	\end{align}
In this case, from the finite propagation, $\bar{z}$ attains the maximum at $(x_*,t_*)$. Then, 
since $\bar{z}_x=0$ and $\bar{z}_t\geq0$, 
we can deduce a contradiction from \eqref{eqn:maximum2}.



\vspace*{1ex}


(Case 4) In this case, we find that $\bar{z}_t(0,t_*)\geq0$ and $\bar{z}_x(0,t_*)\leq0$. Observing Remark \ref{rem:1} (2), since $\lambda_1<0$, we can deduce a contradiction from \eqref{eqn:maximum2}.









\vspace*{1ex}


(Case 5) 		
We set $r=z/w$. Then, if 
$(z,w)\in \Delta_{m,x}$, from $\eqref{eqn:invariant3}_1$, we notice that $-\sigma_1\leq r\leq0$. Then, if 
$(z,w)\in \Delta_{m,x}$, 
we deduce from \eqref{eqn:diagonalization}, \eqref{eqn:f(r)>l} and \eqref{eqn:bar a} 
\begin{align}
	e^{-\int^x_0\bar{a}(y)dy}\left(\underline{w}_t+\lambda_2\underline{w}_x\right)
	=&-a(x)\dfrac{\gamma-1}8\left(w^2-z^2\right)

	+\bar{a}(x)\left(\dfrac{\gamma+1}4w^2+\dfrac{3-\gamma}4zw\right)\nonumber\\
	>& \dfrac{(\gamma-1)\bar{a}(x)|r^2-1|}{8}w^2\left\{f(r)-l\right\}\nonumber\\
	\geq&0.
\label{eqn:maximum3}
\end{align}	
In this case, $\underline{w}$ attains the minimum at $(x_*,t_*)$. Then, since $\underline{w}_x=0$ and $\underline{w}_t\leq0$, 
we can deduce a contradiction from \eqref{eqn:maximum3}.



\vspace*{1ex}


(Case 6) In this case, from the boundary condition $v=0\;(\text{i.e., } w+z=0)$, (Case 4) and $\eqref{eqn:invariant7}_2$, we find that ${w}(0,t_*)=
-{z}(0,t_*)>U_1\geq L_2$.

\vspace*{1ex}


(Case 7) We set $r=z/w$. Then, if 
$(z,w)\in \Delta_{m,x}$, from $\eqref{eqn:invariant1}_2$ and $\eqref{eqn:invariant3}_1$, we 
notice that $-\sigma_1\leq r\leq0$. Then, if 
$(z,w)\in \Delta_{m,x}$, 
we deduce from \eqref{eqn:diagonalization}, \eqref{eqn:f(r)>l} and \eqref{eqn:bar a}  
	  \begin{align}
	e^{\int^x_0\bar{a}(y)dy}\left(\bar{w}_t+\lambda_2\bar{w}_x\right)
	=&-a(x)\dfrac{\gamma-1}8\left(w^2-z^2\right)

	-\bar{a}(x)\left(\dfrac{\gamma+1}4w^2+\dfrac{3-\gamma}4zw\right)\nonumber\\
	<& -\dfrac{(\gamma-1)\bar{a}(x)|r^2-1|}{8}w^2\left\{f(r)-l\right\}\nonumber\\
	\leq&0.
\label{eqn:maximum4}
\end{align}In this case, $\bar{w}$ attains the maximum at $(x_*,t_*)$. Then, since $\bar{w}_x=0$ and $\bar{w}_t\geq0$, 
we can deduce a contradiction from \eqref{eqn:maximum4}.



\vspace*{1ex}


(Case 8) In this case, from the boundary condition $v=0\;(\text{i.e., } w+z=0)$, (Case 3) and $\eqref{eqn:invariant7}_1$, we find that ${w}(0,t_*)=
-{z}(0,t_*)<L_1\leq U_2$.

Since $\varepsilon$ is arbitrary, we can complete the proof of 
Proposition \ref{pro:1}.

\label{pro:2}
	If 
	\begin{align}
		(z_0(x),w_0(x))\in \Delta_{r,x}\quad (z_B(t),w_B(t))\in \Delta_{r,0}\quad

		\text{ for any $x\geq0$ and $t\geq0$}
	\end{align}
	and (P2) has a smooth solution satisfying $\rho\geq0$, $\Delta_{r,x}$ is an invariant region for  (P2).

We first set $\underline{z}=e^{\int^x_0\bar{a}(y)dy}z$ and $r=w/z$. Then, if 
	$(z,w)\in \Delta_{r,x}$, from $\eqref{eqn:invariant6}$, we notice that
	\begin{align*}
		1< r\leq\sigma_2.
	\end{align*}
	Then, if 
	$(z,w)\in \Delta_{r,x}$, we deduce from \eqref{eqn:diagonalization}, \eqref{eqn:f(r)>l} and \eqref{eqn:bar a}  
	\begin{align*}
		e^{-\int^x_0\bar{a}(y)dy}\left(\underline{z}_t+\lambda_1\underline{z}_x\right)
		=&a(x)\dfrac{\gamma-1}8\left(w^2-z^2\right)

		+\bar{a}(x)\left(\dfrac{\gamma+1}4z^2+\dfrac{3-\gamma}4zw\right)\nonumber\\
		>& \dfrac{(\gamma-1)\bar{a}(x)|r^2-1|}{8}z^2\left\{f(r)-l\right\}\nonumber\\
		\geq&0.
	\end{align*}
	We next set $\bar{z}=e^{-\int^x_0\bar{a}(y)dy}z$ and $r=w/z$. Then, if 
	$(z,w)\in \Delta_{r,x}$, from $\eqref{eqn:invariant4}_1$ and $\eqref{eqn:invariant6}$, we notice that
	\begin{align*}
		1< r\leq\sigma_2.
	\end{align*}
	Then, if 
	$(z,w)\in \Delta_{r,x}$, we deduce from \eqref{eqn:diagonalization}, \eqref{eqn:f(r)>l} and \eqref{eqn:bar a}  

	\begin{align*}
		e^{\int^x_0\bar{a}(y)dy}\left(\bar{z}_t+\lambda_1\bar{z}_x\right)
		=&a(x)\dfrac{\gamma-1}8\left(w^2-z^2\right)

		-\bar{a}(x)\left(\dfrac{\gamma+1}4z^2+\dfrac{3-\gamma}4zw\right)\nonumber\\
		\leq& -\dfrac{(\gamma-1)\bar{a}(x)|r^2-1|}{8}z^2\left\{f(r)-l\right\}\nonumber\\
		\leq&0.
	\end{align*}





	We next set $\underline{w}=e^{\int^x_0\bar{a}(y)dy}w$ and $r=z/w$. Then, if 
	$(z,w)\in \Delta_{r,x}$, from $\eqref{eqn:invariant5}$, we notice that $0\leq r<1$. Then, if 
	$(z,w)\in \Delta_{r,x}$, 
	we deduce from \eqref{eqn:diagonalization}, \eqref{eqn:f(r)>l} and \eqref{eqn:bar a}  

	\begin{align*}
		e^{-\int^x_0\bar{a}(y)dy}\left(\underline{w}_t+\lambda_2\underline{w}_x\right)
		=&-a(x)\dfrac{\gamma-1}8\left(w^2-z^2\right)

		+\bar{a}(x)\left(\dfrac{\gamma+1}4w^2+\dfrac{3-\gamma}4zw\right)\nonumber\\
		>& \dfrac{(\gamma-1)\bar{a}(x)|r^2-1|}{8}w^2\left\{f(r)-l\right\}\nonumber\\
		\geq&0.
	\end{align*}	








	Similarly, we first set $\bar{w}=e^{-\int^x_0\bar{a}(y)dy}w$ and set $r=z/w$. Then, if 
	$(z,w)\in \Delta_{r,x}$, from $\eqref{eqn:invariant4}_2$ and $\eqref{eqn:invariant5}$, we 
	notice that $0\leq r<1$. Then, if 
	$(z,w)\in \Delta_{r,x}$, 
	we deduce from \eqref{eqn:diagonalization}, \eqref{eqn:f(r)>l} and \eqref{eqn:bar a}  

	\begin{align}
		e^{\int^x_0\bar{a}(y)dy}\left(\bar{w}_t+\lambda_2\bar{w}_x\right)
		=&-a(x)\dfrac{\gamma-1}8\left(w^2-z^2\right)

		-\bar{a}(x)\left(\dfrac{\gamma+1}4w^2+\dfrac{3-\gamma}4zw\right)\nonumber\\
		<& -\dfrac{(\gamma-1)\bar{a}(x)|r^2-1|}{8}w^2\left\{f(r)-l\right\}\nonumber\\
		\leq&0.
	\end{align}	


	Applying the maximum principle to $\underline{z},\bar{z},
\underline{w}$ and $\bar{w}$, we can complete the proof.

\label{pro:3}
	If 
	\begin{align}
		(z_0(x),w_0(x))\in \Delta_{l,x}\quad\text{ for any $x\geq0$}
	\end{align}
	and (P3) has a smooth solution satisfying $\rho\geq0$, then, $\Delta_{l,x}$ is an invariant region for (P3).
